    public static Map<String, ModelPart> bones(ModelPart root) {
        Map<String, ModelPart> m = new HashMap<>();
        m.put("hull", root.getChild("hull"));
        m.put("nose", root.getChild("hull").getChild("nose"));
        m.put("arm_right", root.getChild("hull").getChild("arm_right"));
        m.put("barrels_right", root.getChild("hull").getChild("arm_right").getChild("barrels_right"));
        m.put("arm_left", root.getChild("hull").getChild("arm_left"));
        m.put("barrels_left", root.getChild("hull").getChild("arm_left").getChild("barrels_left"));
        m.put("pod", root.getChild("hull").getChild("arm_left").getChild("pod"));
        m.put("left_thigh", root.getChild("left_thigh"));
        m.put("left_shin", root.getChild("left_thigh").getChild("left_shin"));
        m.put("left_foot", root.getChild("left_thigh").getChild("left_shin").getChild("left_foot"));
        m.put("right_thigh", root.getChild("right_thigh"));
        m.put("right_shin", root.getChild("right_thigh").getChild("right_shin"));
        m.put("right_foot", root.getChild("right_thigh").getChild("right_shin").getChild("right_foot"));
        return m;
    }

